const ELEMENT_PROP_KEYS = new Set(["theme","dropAt","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  dropAt: 44,
  stagger: 14,
  fontFamily: "Barlow Condensed",
  scale: 1,
  delay: 0,
  speed: 1,
};

type NegationDropElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof NegationDropBase>;

const NegationDropInner = forwardRef<
  HTMLDivElement,
  NegationDropElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<NegationDrop>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <NegationDropBase
          {...(componentProps as unknown as ComponentProps<typeof NegationDropBase>)}
        />
      </div>
    </Sequence>
  );
});

export const NegationDrop = Interactive.withSchema({
  Component: NegationDropInner,
  componentName: "<NegationDrop>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
